      ui.stageInfo.textContent = `${fmtInt(crop.w)}×${fmtInt(crop.h)} → ${fmtInt(ov.width)}×${fmtInt(ov.height)}`;
      ui.zoomLabel.textContent = `${Math.round(viewScale * 100)}%`;
      void p;
